solution.code:
#include <stdio.h>

enum Level { LOW = 1, MEDIUM = 5, HIGH = 10 };

int main() {
    enum Level level = MEDIUM;
    printf("MEDIUM=%d HIGH=%d\n", MEDIUM, HIGH);
    printf("Double: %d\n", level * 2);
    return 0;
}
